ALTER TABLE public.expense_recurring_rules ADD COLUMN IF NOT EXISTS is_contract boolean NOT NULL DEFAULT false, ADD COLUMN IF NOT EXISTS direction text NOT NULL DEFAULT 'cost', ADD COLUMN IF NOT EXISTS billed_when text NOT NULL DEFAULT 'arrears', ADD COLUMN IF NOT EXISTS contract_end date, ADD COLUMN IF NOT EXISTS central_share_method text NOT NULL DEFAULT 'sales', ADD COLUMN IF NOT EXISTS rent_free_months jsonb NOT NULL DEFAULT '[]', ADD COLUMN IF NOT EXISTS step_increases jsonb NOT NULL DEFAULT '[]', ADD COLUMN IF NOT EXISTS deposit_amount numeric NOT NULL DEFAULT 0, ADD COLUMN IF NOT EXISTS attachment_path text, ADD COLUMN IF NOT EXISTS attachment_url text;
UPDATE public.expense_recurring_rules SET is_contract=true WHERE id='a265f411-4e0d-44ae-afc8-948101852140' AND name='Monthly Rental Expense (Knustford Terrace Venue)';
CREATE TABLE public.expense_accrual_drafts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,recurring_rule_id uuid REFERENCES public.expense_recurring_rules(id),supplier_id uuid REFERENCES public.suppliers(id),venue_id uuid REFERENCES public.venues(id),venue text,month_start date NOT NULL,amount numeric NOT NULL DEFAULT 0,account_id uuid REFERENCES public.chart_of_accounts(id),direction text NOT NULL DEFAULT 'cost',kind text NOT NULL DEFAULT 'contract',status text NOT NULL DEFAULT 'waiting',reason text NOT NULL DEFAULT '',source_key text NOT NULL,journal_entry_id uuid REFERENCES public.journal_entries(id),reversal_entry_id uuid REFERENCES public.journal_entries(id),actual_bill_id uuid REFERENCES public.expense_bills(id),created_by uuid,approved_by uuid,approved_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,source_key,month_start));
GRANT SELECT,INSERT,UPDATE ON public.expense_accrual_drafts TO authenticated; GRANT ALL ON public.expense_accrual_drafts TO service_role;
ALTER TABLE public.expense_accrual_drafts ENABLE ROW LEVEL SECURITY;
CREATE POLICY accrual_read ON public.expense_accrual_drafts FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id) AND (venue_id IS NULL OR public.user_has_venue(auth.uid(),venue_id)));
CREATE POLICY accrual_draft_insert ON public.expense_accrual_drafts FOR INSERT TO authenticated WITH CHECK(public.user_has_tenant(auth.uid(),tenant_id) AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) AND status='waiting' AND journal_entry_id IS NULL AND reversal_entry_id IS NULL AND approved_at IS NULL AND (venue_id IS NULL OR public.user_has_venue(auth.uid(),venue_id)));
CREATE TABLE public.expense_correction_proposals(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL,kind text NOT NULL,original_entry_id uuid REFERENCES public.journal_entries(id),title text NOT NULL,reason text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'draft',created_at timestamptz NOT NULL DEFAULT now(),approved_by uuid,approved_at timestamptz,adjustment_entry_id uuid REFERENCES public.journal_entries(id),UNIQUE(tenant_id,kind,original_entry_id));
GRANT SELECT,INSERT ON public.expense_correction_proposals TO authenticated; GRANT ALL ON public.expense_correction_proposals TO service_role;
ALTER TABLE public.expense_correction_proposals ENABLE ROW LEVEL SECURITY;
CREATE POLICY correction_read ON public.expense_correction_proposals FOR SELECT TO authenticated USING(public.user_has_tenant(auth.uid(),tenant_id));
CREATE POLICY correction_propose ON public.expense_correction_proposals FOR INSERT TO authenticated WITH CHECK(public.user_has_tenant(auth.uid(),tenant_id) AND (public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) AND status='draft' AND approved_at IS NULL AND adjustment_entry_id IS NULL);
ALTER TABLE public.payment_settlement_lines ADD COLUMN IF NOT EXISTS venue text;
CREATE OR REPLACE FUNCTION public.expense_accrual_approve(p_id uuid) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE d public.expense_accrual_drafts%ROWTYPE;r public.expense_recurring_rules%ROWTYPE;j uuid;contra uuid;v record;ln int:=0;total numeric:=0;part numeric;weights numeric;last_id uuid;
BEGIN
SELECT * INTO d FROM public.expense_accrual_drafts WHERE id=p_id FOR UPDATE;
IF NOT FOUND OR NOT public.user_has_tenant(auth.uid(),d.tenant_id) OR NOT(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) OR (d.venue_id IS NOT NULL AND NOT public.user_has_venue(auth.uid(),d.venue_id)) THEN RAISE EXCEPTION 'Expense approval access required';END IF;
IF d.status='posted' THEN RETURN d.journal_entry_id; END IF;
IF d.status<>'waiting' OR d.amount<0 OR d.account_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.chart_of_accounts WHERE id=d.account_id AND tenant_id=d.tenant_id AND is_active) THEN RAISE EXCEPTION 'Draft is not ready';END IF;
PERFORM public.finance_assert_open(d.tenant_id,(d.month_start+interval '1 month - 1 day')::date);
IF d.recurring_rule_id IS NOT NULL THEN
SELECT * INTO r FROM public.expense_recurring_rules WHERE id=d.recurring_rule_id AND tenant_id=d.tenant_id;
IF NOT FOUND OR NOT r.is_contract OR r.status<>'active' THEN RAISE EXCEPTION 'An active contract is required';END IF;
IF EXISTS(SELECT 1 FROM public.expense_bills b WHERE b.recurring_rule_id=r.id AND date_trunc('month',coalesce(b.period_start,b.bill_date))::date=d.month_start AND b.approval_status='posted') THEN RAISE EXCEPTION 'This contract month already has a booked bill';END IF;
IF EXISTS(SELECT 1 FROM public.journal_entries e JOIN public.journal_lines l ON l.entry_id=e.id WHERE e.tenant_id=d.tenant_id AND e.status='posted' AND e.source_type='manual' AND date_trunc('month',e.entry_date)::date=d.month_start AND l.account_id=d.account_id AND abs(l.debit-l.credit-d.amount)<.01) THEN RAISE EXCEPTION 'Same month is already booked by hand; owner correction required';END IF;
END IF;
SELECT id INTO contra FROM public.chart_of_accounts WHERE tenant_id=d.tenant_id AND lower(name)=CASE WHEN d.direction='income' THEN 'accrued income' ELSE 'accrued expenses' END AND is_active ORDER BY code LIMIT 1;
IF contra IS NULL THEN RAISE EXCEPTION 'Accrual account is missing';END IF;
INSERT INTO public.journal_entries(tenant_id,entry_date,memo,source_type,source_id,status,created_by) VALUES(d.tenant_id,(d.month_start+interval '1 month - 1 day')::date,coalesce(r.name,d.reason)||' · '||d.kind,'expense_accrual',d.id::text,'draft',auth.uid()) RETURNING id INTO j;
IF d.venue_id IS NULL AND d.recurring_rule_id IS NOT NULL THEN
SELECT coalesce(sum(total_sales),0) INTO weights FROM public.sales_records WHERE tenant_id=d.tenant_id AND date>=d.month_start AND date<d.month_start+interval '1 month';
IF weights<=0 THEN RAISE EXCEPTION 'Central sales split needs sales evidence for this month';END IF;
SELECT vv.id INTO last_id FROM public.venues vv JOIN public.sales_records s ON s.venue=vv.name AND s.tenant_id=vv.tenant_id WHERE vv.tenant_id=d.tenant_id AND s.date>=d.month_start AND s.date<d.month_start+interval '1 month' GROUP BY vv.id ORDER BY vv.id DESC LIMIT 1;
FOR v IN SELECT vv.id,vv.name,sum(s.total_sales) sales FROM public.venues vv JOIN public.sales_records s ON s.venue=vv.name AND s.tenant_id=vv.tenant_id WHERE vv.tenant_id=d.tenant_id AND s.date>=d.month_start AND s.date<d.month_start+interval '1 month' GROUP BY vv.id,vv.name ORDER BY vv.id LOOP
part:=CASE WHEN v.id=last_id THEN d.amount-total ELSE round(d.amount*v.sales/weights,2) END;total:=total+part;ln:=ln+1;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,venue_id,line_no,memo) VALUES(d.tenant_id,j,d.account_id,CASE WHEN d.direction='cost' THEN part ELSE 0 END,CASE WHEN d.direction='income' THEN part ELSE 0 END,v.name,v.id,ln,'Central · by sales');END LOOP;
ELSE ln:=1;INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,venue,venue_id,line_no,memo) VALUES(d.tenant_id,j,d.account_id,CASE WHEN d.direction='cost' THEN d.amount ELSE 0 END,CASE WHEN d.direction='income' THEN d.amount ELSE 0 END,d.venue,d.venue_id,ln,d.kind);END IF;
INSERT INTO public.journal_lines(tenant_id,entry_id,account_id,debit,credit,line_no,memo) VALUES(d.tenant_id,j,contra,CASE WHEN d.direction='income' THEN d.amount ELSE 0 END,CASE WHEN d.direction='cost' THEN d.amount ELSE 0 END,ln+1,d.kind);
UPDATE public.journal_entries SET status='posted',posted_at=now() WHERE id=j;
UPDATE public.expense_accrual_drafts SET status='posted',journal_entry_id=j,approved_by=auth.uid(),approved_at=now() WHERE id=d.id;RETURN j;END $$;
REVOKE ALL ON FUNCTION public.expense_accrual_approve(uuid) FROM PUBLIC;GRANT EXECUTE ON FUNCTION public.expense_accrual_approve(uuid) TO authenticated;
COMMENT ON TABLE public.expense_accrual_drafts IS 'Source-linked contract/variable estimates, explicit approval by default; posted evidence retained.';